<script>
import ImgPrefixer from '../../../components/blogs/ImgPrefixer.vue';
export default {
  components: { ImgPrefixer },
  name: "BlogDetails",
  head() {
    return {
      title: "Blog Details",
    };
  },
  data(){
    return {
        blog:{}
    }
  },
  computed: {
    slug() {
      return this.$route.params?.details;
    },
    appName() {
      return process.env.APP_NAME || "";
    },
    backendUrl(){
      const backendApi = process.env.BACKEND_API;
      return backendApi.replace('/api', '');
     }
  },
  mounted() {
    this.getBlog();
  },
  methods: {
    getBlog() {
      this.$axios
        .get(`/blogs/${this.slug}`)
        .then((res) => {
            this.blog = res.data
            this.$log(res.data);
        })
        .catch((err) => {
          this.$elog(err.response);
        });
    },
    imageUrlAlt(event) {
      event.target.src = "/assets/images/blogs/blog-detail.png";
    },
  },
};
</script>